const required = ['DATABASE_URL', 'UPLOAD_BUCKET', 'EXPORT_BUCKET', 'SESSION_SECRET'] as const;

export function loadConfig() {
  const missing = required.filter((name) => !process.env[name]);
  if (missing.length) throw new Error(`Missing required config: ${missing.join(', ')}`);
  return Object.fromEntries(required.map((name) => [name, process.env[name]!]));
}
